constexpr unsigned W=64,H=64;uint64_t checks=0;NSMutableArray* observations;
void Check(bool b,const char* m){++checks;Require(b,m);}
std::shared_ptr<ScreenTexture> Image(const std::string& file){auto p=std::make_shared<ScreenTexture>();p->sourceName=file;p->width=p->height=512;p->bytesPerRow=2048;p->generateMipmaps=true;std::ifstream f(file,std::ios::binary);p->bytes.assign(std::istreambuf_iterator<char>(f),{});Check(p->bytes.size()==512*512*4,"Actual source PNG payload missing");return p;}
std::shared_ptr<ScreenTexture> Stripes(){auto p=std::make_shared<ScreenTexture>();p->sourceName="independent anisotropy stripe oracle";p->width=p->height=512;p->bytesPerRow=2048;p->generateMipmaps=true;p->bytes.resize(512*512*4);for(unsigned y=0;y<512;++y)for(unsigned x=0;x<512;++x){auto k=(y*512+x)*4;p->bytes[k]=p->bytes[k+1]=p->bytes[k+2]=y/64%2?255:0;p->bytes[k+3]=255;}return p;}
struct GLReference {CGLContextObj context=nullptr;GLuint fbo=0,out=0,texture=0;GLReference(){CGLPixelFormatAttribute a[]={kCGLPFAAccelerated,kCGLPFAColorSize,CGLPixelFormatAttribute(24),kCGLPFAAlphaSize,CGLPixelFormatAttribute(8),CGLPixelFormatAttribute(0)};CGLPixelFormatObj p=nullptr;GLint n=0;Check(CGLChoosePixelFormat(a,&p,&n)==kCGLNoError&&p,"CGL format unavailable");auto e=CGLCreateContext(p,nullptr,&context);CGLDestroyPixelFormat(p);Check(e==kCGLNoError&&context,"CGL unavailable");CGLSetCurrentContext(context);glGenFramebuffersEXT(1,&fbo);glBindFramebufferEXT(GL_FRAMEBUFFER_EXT,fbo);glGenTextures(1,&out);glBindTexture(GL_TEXTURE_2D,out);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,W,H,0,GL_RGBA,GL_UNSIGNED_BYTE,nullptr);glFramebufferTexture2DEXT(GL_FRAMEBUFFER_EXT,GL_COLOR_ATTACHMENT0_EXT,GL_TEXTURE_2D,out,0);Check(glCheckFramebufferStatusEXT(GL_FRAMEBUFFER_EXT)==GL_FRAMEBUFFER_COMPLETE_EXT,"CGL target incomplete");glGenTextures(1,&texture);}
~GLReference(){if(context){CGLSetCurrentContext(context);glDeleteTextures(1,&texture);glDeleteTextures(1,&out);glDeleteFramebuffersEXT(1,&fbo);CGLSetCurrentContext(nullptr);CGLDestroyContext(context);}}
std::vector<std::vector<uint8_t>> Mips(const ScreenTexture& p){CGLSetCurrentContext(context);glBindTexture(GL_TEXTURE_2D,texture);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA8,p.width,p.height,0,GL_RGBA,GL_UNSIGNED_BYTE,p.bytes.data());glGenerateMipmapEXT(GL_TEXTURE_2D);std::vector<std::vector<uint8_t>> result;for(unsigned s=p.width,level=0;;s=std::max(1u,s/2),++level){result.emplace_back(s*s*4);glGetTexImage(GL_TEXTURE_2D,level,GL_RGBA,GL_UNSIGNED_BYTE,result.back().data());if(s==1)break;}Check(glGetError()==GL_NO_ERROR,"Original GL GPU mip generation failed");return result;}
std::vector<uint8_t> Draw(const ScreenTexture& p,const ScreenSampler& sampler,float spanX=1,float spanY=1){Mips(p);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,sampler.mipFilter==ScreenMipFilter::None?GL_LINEAR:GL_LINEAR_MIPMAP_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_REPEAT);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_REPEAT);glTexParameterf(GL_TEXTURE_2D,GL_TEXTURE_MAX_ANISOTROPY_EXT,sampler.anisotropy);glEnable(GL_TEXTURE_2D);glDisable(GL_DITHER);glDisable(GL_LIGHTING);glDisable(GL_FOG);glDisable(GL_BLEND);glDisable(GL_DEPTH_TEST);glDisable(GL_CULL_FACE);glViewport(0,0,W,H);glMatrixMode(GL_PROJECTION);glLoadIdentity();glOrtho(0,W,0,H,-1,1);glMatrixMode(GL_MODELVIEW);glLoadIdentity();glColor4f(1,1,1,1);glBegin(GL_QUADS);glTexCoord2f(0,0);glVertex2f(0,0);glTexCoord2f(spanX,0);glVertex2f(W,0);glTexCoord2f(spanX,spanY);glVertex2f(W,H);glTexCoord2f(0,spanY);glVertex2f(0,H);glEnd();std::vector<uint8_t>b(W*H*4),t(b.size());glReadPixels(0,0,W,H,GL_RGBA,GL_UNSIGNED_BYTE,b.data());Check(glGetError()==GL_NO_ERROR,"Original GL sampler draw failed");for(unsigned y=0;y<H;++y)std::memcpy(t.data()+y*W*4,b.data()+(H-1-y)*W*4,W*4);return t;}
};
struct Rendered {std::vector<uint8_t> pixels;__strong id<MTLTexture> image=nil;__strong id<MTLSamplerState> sampler=nil;unsigned generated=0;};
Rendered Render(ScreenGPU& gpu,const std::shared_ptr<const ScreenTexture>& source,ScreenSampler sampler,bool abort=false,float spanX=1,float spanY=1){RuntimeLease lease;double ms=0;ScreenDrawState state;state.material=ScreenMaterial::RGBA;state.texture=source;state.sampler=sampler;state.blend.enabled=false;ScreenDrawList list;const std::array<ScreenVertex,4> v{{{0,0,0,{1,1,1,1}},{W,0,0,{1,1,1,1}},{W,H,0,{1,1,1,1}},{0,H,0,{1,1,1,1}}}};const std::array<ScreenTexCoord,4> uv{{{0,0,0,0},{spanX,0,0,0},{spanX,spanY,0,0},{0,spanY,0,0}}};const std::array<uint32_t,6> idx{0,1,2,0,2,3};list.AppendTriangles(v,uv,idx,state);auto frame=gpu.Prepare(lease,{&list,W,H,{},{}},W,H,W,H,MTLPixelFormatRGBA8Unorm,true,ms);auto image=gpu.PrepareImage(lease,source,sampler,frame.get());auto mips=gpu.PrepareMipmaps(lease);Rendered result;result.image=image.texture;result.sampler=image.sampler;result.generated=mips->TextureCount();if(abort)return result;auto d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA8Unorm width:W height:H mipmapped:NO];d.storageMode=MTLStorageModeShared;d.usage=MTLTextureUsageRenderTarget;auto output=[lease.Device() newTextureWithDescriptor:d];Check(output!=nil,"Native target allocation failed");lease.AddAllocation(output);lease.CommitResources();auto cmd=lease.Begin("Original named image generation/filter oracle");mips->EncodeDependencies(cmd);frame->EncodeDependencies(cmd);auto pass=[MTL4RenderPassDescriptor new];pass.colorAttachments[0].texture=output;pass.colorAttachments[0].loadAction=MTLLoadActionClear;pass.colorAttachments[0].storeAction=MTLStoreActionStore;pass.renderTargetWidth=W;pass.renderTargetHeight=H;auto encoder=[cmd renderCommandEncoderWithDescriptor:pass];Check(encoder!=nil,"Native screen encoder failed");frame->Encode(encoder);[encoder endEncoding];lease.SubmitAndWait(Clock::now(),0);frame->DidComplete();mips->DidComplete();result.pixels=lease.Readback(output,W,H,ms);return result;}
NSDictionary* Compare(const std::vector<uint8_t>& a,const std::vector<uint8_t>& b,unsigned tolerance=1){Check(a.size()==b.size(),"Compared byte extents differ");uint64_t bad=0;unsigned maximum=0;for(size_t i=0;i<a.size();++i){unsigned d=std::abs(int(a[i])-int(b[i]));bad+=d>tolerance;maximum=std::max(d,maximum);++checks;}return @{@"badChannels":@(bad),@"maximumDifference":@(maximum),@"tolerance":@(tolerance),@"checks":@(a.size())};}
void MipCompare(GLReference& gl,const ScreenTexture& source,id<MTLTexture> image){auto expected=gl.Mips(source);Check(image.mipmapLevelCount==expected.size(),"Native complete mip count differs from original");uint64_t bad=0;unsigned maximum=0;for(unsigned level=0,s=source.width;level<expected.size();++level,s=std::max(1u,s/2)){std::vector<uint8_t> actual(s*s*4);[image getBytes:actual.data() bytesPerRow:s*4 fromRegion:MTLRegionMake2D(0,0,s,s) mipmapLevel:level];auto r=Compare(expected[level],actual);bad+=[r[@"badChannels"] unsignedLongLongValue];maximum=std::max(maximum,[r[@"maximumDifference"] unsignedIntValue]);} [observations addObject:@{@"case":@"Actual original GPU-generated complete mip chain",@"source":String(source.sourceName),@"badChannels":@(bad),@"maximumDifference":@(maximum),@"tolerance":@1}];Check(bad==0,"Original GL/native GPU-generated mip chain differs beyond fixed 1LSB gate");}
}
int main(int argc,char** argv){@autoreleasepool{observations=[NSMutableArray array];try{Check(argc==3||argc==4,"work directory and report required");const std::string dir=argv[1];if(argc==4){ScreenGPU gpu;const auto n=unsigned(std::stoul(argv[3]));auto t=std::make_shared<ScreenTexture>();t->sourceName="Original base-only DDS compressed GPU generation capability";t->width=t->height=8;t->format=n==1?ScreenTextureFormat::BC1RGBA:n==2?ScreenTextureFormat::BC2RGBA:ScreenTextureFormat::BC3RGBA;t->generateMipmaps=true;const unsigned block=n==1?8:16;ScreenTextureMip base;base.width=base.height=8;base.bytesPerRow=2*block;base.bytes.resize(4*block);for(unsigned b=0;b<4;++b){auto* dst=base.bytes.data()+b*block;if(n==2)std::fill(dst,dst+8,255);if(n==3)dst[0]=dst[1]=255;dst+=n==1?0:8;dst[0]=dst[1]=dst[2]=dst[3]=255;}t->mips.push_back(std::move(base));ScreenSampler sample;sample.mipFilter=ScreenMipFilter::Linear;auto r=Render(gpu,t,sample);Check(r.generated==1&&r.image.mipmapLevelCount==4,"DDS base-only full chain not produced");for(auto v:r.pixels)Check(v==255,"DDS generated constant-white chain changed color/alpha");NSData* j=[NSJSONSerialization dataWithJSONObject:@{@"status":@"passed",@"format":@(n),@"checks":@(checks)} options:NSJSONWritingPrettyPrinted error:nil];[j writeToFile:String(argv[2]) atomically:YES];std::cout<<"PASS BC"<<n<<" checks="<<checks<<'\n';return 0;}GLReference gl;ScreenGPU gpu;auto fog=Image(dir+"/fog0.rgba"),fog2=Image(dir+"/fog1.rgba");auto sampler=GetNativeNamedImagePolicy(ParseNativeUITextureQualifiers(":a:fog.png"),false,512,512,0,16).sampler;
auto aborted=Render(gpu,fog,sampler,true);Check(aborted.generated==1,"Unsubmitted original image did not schedule one GPU producer");auto first=Render(gpu,fog,sampler);Check(first.generated==1,"Aborted mip plan incorrectly published initialization");MipCompare(gl,*fog,first.image);auto second=Render(gpu,fog,sampler);Check(second.generated==0&&first.image==second.image,"Retired immutable mip owner was regenerated/reallocated");Check(first.pixels==second.pixels,"Unchanged owner output differs");auto replacement=Render(gpu,fog2,sampler);Check(replacement.generated==1&&replacement.image!=first.image,"New immutable owner did not generate a new native chain");MipCompare(gl,*fog2,replacement.image);
// Ordinary isotropic minification compares actual original API generation+sampling.
auto iso=sampler;iso.anisotropy=1;auto isoNative=Render(gpu,fog,iso);auto compare=Compare(gl.Draw(*fog,iso),isoNative.pixels);[observations addObject:@{@"case":@"Actual original fog isotropic minification",@"comparison":compare}];Check([compare[@"badChannels"] unsignedLongLongValue]==0,"Original fog minification exceeds fixed 1LSB gate");
// Independent highly anisotropic footprint: y detail must survive long x footprint.
auto stripe=Stripes();auto aniso=Render(gpu,stripe,sampler,false,16,1);auto original=gl.Draw(*stripe,sampler,16,1);auto ac=Compare(original,aniso.pixels);[observations addObject:@{@"case":@"Anisotropic original footprint",@"comparison":ac}];Check([ac[@"badChannels"] unsignedLongLongValue]==0,"Anisotropic source footprint differs beyond fixed 1LSB gate");auto missing=Render(gpu,stripe,iso,false,16,1);auto nc=Compare(original,missing.pixels);Check([nc[@"badChannels"] unsignedLongLongValue]>0,"Omitted anisotropy negative is not distinguishable");[observations addObject:@{@"case":@"Negative omitted anisotropy",@"comparison":nc}];Check(first.sampler!=isoNative.sampler,"Anisotropy is missing from native sampler cache key");
// b changes stored border color; default repeat must remain repeat.
auto border=iso;border.wrapS=border.wrapT=ScreenWrap::TransparentBorder;border.whiteBorder=true;auto white=Render(gpu,fog,border,false,0,0);border.whiteBorder=false;auto black=Render(gpu,fog,border,false,0,0);Check(white.sampler!=black.sampler&&white.pixels!=black.pixels,"Original border color was ignored or omitted from sampler key");
// Existing embedded chain is never regenerated or overwritten.
auto explicitImage=std::make_shared<ScreenTexture>();explicitImage->width=explicitImage->height=2;explicitImage->mips={{2,2,8,{255,0,0,255,255,0,0,255,255,0,0,255,255,0,0,255}},{1,1,4,{0,255,0,255}}};auto explicitDraw=Render(gpu,explicitImage,iso);Check(explicitDraw.generated==0&&explicitDraw.image.mipmapLevelCount==2,"Embedded original mip chain was generated/changed");uint8_t green[4]{};[explicitDraw.image getBytes:green bytesPerRow:4 fromRegion:MTLRegionMake2D(0,0,1,1) mipmapLevel:1];Check(green[0]==0&&green[1]==255&&green[2]==0&&green[3]==255,"Embedded source mip bytes changed");auto competing=std::make_shared<ScreenTexture>(*explicitImage);competing->generateMipmaps=true;bool rejected=false;try{Render(gpu,competing,iso);}catch(const std::exception&){rejected=true;}Check(rejected,"Competing generated+embedded chain was accepted");
gpu.ClearResources();auto reset=Render(gpu,fog,iso);Check(reset.generated==1&&reset.image!=first.image,"ClearResources retained old image producer state");Check(reset.pixels==isoNative.pixels,"Cache reset changed actual image output");
NSMutableDictionary* report=[@{@"status":@"passed",@"checks":@(checks),@"observations":observations,@"shaderValidation":@YES,@"apiValidation":@YES}mutableCopy];NSData* json=[NSJSONSerialization dataWithJSONObject:report options:NSJSONWritingPrettyPrinted error:nil];Check([json writeToFile:String(argv[2]) atomically:YES],"Report save failed");std::cout<<"PASS checks="<<checks<<" observations="<<observations.count<<'\n';return 0;
}catch(const std::exception& e){NSDictionary* r=@{@"status":@"failed",@"error":String(e.what()),@"checks":@(checks),@"observations":observations};if(argc>2){NSData* j=[NSJSONSerialization dataWithJSONObject:r options:NSJSONWritingPrettyPrinted error:nil];[j writeToFile:String(argv[2]) atomically:YES];}std::cerr<<"FAIL "<<e.what()<<" checks="<<checks<<'\n';return 1;}}}
